// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable2Step, Ownable} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

/// @title PearlLPStaking
/// @notice Stake PEARL-WETH LP and earn an arbitrary number of reward tokens, each
///         streamed per-second at its own rate. Exiting requires a cooldown during
///         which the staked amount stops earning. No lock, no boost, no position token.
/// @dev    Reward engine is Synthetix/Curve MultiRewards: a per-token rewardPerToken
///         accumulator keyed by user address. Weight == earning balance (1:1, no multiplier),
///         so reward state only changes on discrete user actions and accounting stays O(1)
///         per token. Cooldown is one slot per address; starting a new cooldown adds to the
///         pending amount and resets the clock on the combined total. rewardsOwed tracks
///         streamed-but-unclaimed rewards per token (conservatively ceil-rounded), which
///         lets the owner recover un-streamed excess (empty-pool periods, donations) via
///         recoverExcessRewardToken and makes the notify solvency check exact.
contract PearlLPStaking is Ownable2Step, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    uint256 public constant MAX_REWARD_TOKENS = 20;
    uint256 public constant MIN_DURATION = 1 hours;
    uint256 public constant MAX_DURATION = 365 days;
    uint256 public constant MAX_COOLDOWN = 30 days;

    IERC20 public immutable stakingToken;

    uint256 public cooldownPeriod = 7 days;

    mapping(address => uint256) public balanceOf;
    uint256 public totalStaked;

    mapping(address => uint256) public coolingDown;
    mapping(address => uint256) public cooldownEnd;

    struct RewardData {
        uint256 rewardRate;
        uint64 periodFinish;
        uint64 lastUpdateTime;
        uint256 rewardPerTokenStored;
        bool exists;
    }

    address[] public rewardTokens;
    mapping(address => RewardData) public rewardData;
    mapping(address => address) public rewardDistributor;
    mapping(address => mapping(address => uint256)) public userRewardPerTokenPaid;
    mapping(address => mapping(address => uint256)) public rewards;

    /// @notice Streamed-but-unclaimed rewards per token, accrued whenever the global
    ///         accumulator advances. Ceil-rounded so it always covers the sum of what
    ///         users can eventually claim; rounding dust errs toward staying reserved.
    mapping(address => uint256) public rewardsOwed;

    event Staked(address indexed user, uint256 amount);
    event CooldownStarted(address indexed user, uint256 amount, uint256 totalCooling, uint256 cooldownEnd);
    event CooldownCancelled(address indexed user, uint256 amount, uint256 remainingCooling);
    event Withdrawn(address indexed user, uint256 amount);
    event RewardPaid(address indexed user, address indexed token, uint256 amount);
    event RewardTokenAdded(address indexed token, address indexed distributor);
    event RewardNotified(address indexed token, uint256 amount, uint256 duration, uint256 rate, uint64 periodFinish);
    event RewardDistributorUpdated(address indexed token, address indexed distributor);
    event CooldownPeriodUpdated(uint256 cooldownPeriod);
    event Recovered(address indexed token, uint256 amount);
    event RewardExcessRecovered(address indexed token, uint256 amount);

    constructor(address _stakingToken, address _owner) Ownable(_owner) {
        require(_stakingToken != address(0), "staking token zero");
        stakingToken = IERC20(_stakingToken);
    }

    modifier updateReward(address account) {
        uint256 len = rewardTokens.length;
        for (uint256 i; i < len; ++i) {
            address token = rewardTokens[i];
            RewardData storage r = rewardData[token];
            uint256 newPerToken = rewardPerToken(token);
            uint256 deltaPerToken = newPerToken - r.rewardPerTokenStored;
            if (deltaPerToken != 0 && totalStaked != 0) {
                // Ceil so rewardsOwed >= the sum of user claims: users floor
                // balance * accumulatedDelta across many intervals in one division,
                // which can exceed the sum of per-interval global floors by dust.
                rewardsOwed[token] += Math.ceilDiv(deltaPerToken * totalStaked, 1e18);
            }
            r.rewardPerTokenStored = newPerToken;
            r.lastUpdateTime = uint64(lastTimeRewardApplicable(token));
            if (account != address(0)) {
                rewards[token][account] = earned(account, token);
                userRewardPerTokenPaid[token][account] = r.rewardPerTokenStored;
            }
        }
        _;
    }

    modifier onlyDistributor(address token) {
        require(msg.sender == rewardDistributor[token] || msg.sender == owner(), "not distributor");
        _;
    }

    function stake(uint256 amount) external nonReentrant whenNotPaused updateReward(msg.sender) {
        require(amount > 0, "zero amount");
        balanceOf[msg.sender] += amount;
        totalStaked += amount;
        stakingToken.safeTransferFrom(msg.sender, address(this), amount);
        emit Staked(msg.sender, amount);
    }

    function startCooldown(uint256 amount) external nonReentrant updateReward(msg.sender) {
        require(amount > 0, "zero amount");
        require(amount <= balanceOf[msg.sender], "exceeds staked");
        balanceOf[msg.sender] -= amount;
        totalStaked -= amount;
        uint256 newCooling = coolingDown[msg.sender] + amount;
        coolingDown[msg.sender] = newCooling;
        cooldownEnd[msg.sender] = block.timestamp + cooldownPeriod;
        emit CooldownStarted(msg.sender, amount, newCooling, cooldownEnd[msg.sender]);
    }

    function cancelCooldown(uint256 amount) external nonReentrant updateReward(msg.sender) {
        require(amount > 0, "zero amount");
        uint256 cooling = coolingDown[msg.sender];
        require(amount <= cooling, "exceeds cooling");
        uint256 remaining = cooling - amount;
        coolingDown[msg.sender] = remaining;
        if (remaining == 0) cooldownEnd[msg.sender] = 0;
        balanceOf[msg.sender] += amount;
        totalStaked += amount;
        emit CooldownCancelled(msg.sender, amount, remaining);
    }

    function withdraw(uint256 amount) external nonReentrant {
        require(amount > 0, "zero amount");
        require(amount <= coolingDown[msg.sender], "exceeds cooling");
        require(block.timestamp >= cooldownEnd[msg.sender], "cooldown not elapsed");
        coolingDown[msg.sender] -= amount;
        stakingToken.safeTransfer(msg.sender, amount);
        emit Withdrawn(msg.sender, amount);
    }

    function getReward() public nonReentrant updateReward(msg.sender) {
        uint256 len = rewardTokens.length;
        for (uint256 i; i < len; ++i) {
            _payReward(rewardTokens[i], msg.sender);
        }
    }

    function getReward(address[] calldata tokens) external nonReentrant updateReward(msg.sender) {
        for (uint256 i; i < tokens.length; ++i) {
            require(rewardData[tokens[i]].exists, "unknown reward token");
            _payReward(tokens[i], msg.sender);
        }
    }

    function _payReward(address token, address user) internal {
        uint256 amount = rewards[token][user];
        if (amount > 0) {
            rewards[token][user] = 0;
            // Saturating: ceil rounding keeps rewardsOwed >= claims, but a wei-level
            // rounding argument must never be able to brick getReward.
            uint256 owed = rewardsOwed[token];
            rewardsOwed[token] = amount >= owed ? 0 : owed - amount;
            IERC20(token).safeTransfer(user, amount);
            emit RewardPaid(user, token, amount);
        }
    }

    function lastTimeRewardApplicable(address token) public view returns (uint256) {
        uint256 finish = rewardData[token].periodFinish;
        return block.timestamp < finish ? block.timestamp : finish;
    }

    function rewardPerToken(address token) public view returns (uint256) {
        RewardData storage r = rewardData[token];
        if (totalStaked == 0) return r.rewardPerTokenStored;
        uint256 delta = lastTimeRewardApplicable(token) - r.lastUpdateTime;
        return r.rewardPerTokenStored + (delta * r.rewardRate * 1e18) / totalStaked;
    }

    function earned(address account, address token) public view returns (uint256) {
        uint256 perToken = rewardPerToken(token) - userRewardPerTokenPaid[token][account];
        return (balanceOf[account] * perToken) / 1e18 + rewards[token][account];
    }

    function claimableRewards(address account)
        external
        view
        returns (address[] memory tokens, uint256[] memory amounts)
    {
        uint256 len = rewardTokens.length;
        tokens = new address[](len);
        amounts = new uint256[](len);
        for (uint256 i; i < len; ++i) {
            tokens[i] = rewardTokens[i];
            amounts[i] = earned(account, rewardTokens[i]);
        }
    }

    function rewardForRemainingPeriod(address token) external view returns (uint256) {
        RewardData storage r = rewardData[token];
        if (block.timestamp >= r.periodFinish) return 0;
        return r.rewardRate * (r.periodFinish - block.timestamp);
    }

    function rewardPerYear(address token) external view returns (uint256) {
        return rewardData[token].rewardRate * 365 days;
    }

    function cooldownInfo(address user)
        external
        view
        returns (uint256 cooling, uint256 endsAt, bool withdrawable)
    {
        cooling = coolingDown[user];
        endsAt = cooldownEnd[user];
        withdrawable = cooling > 0 && block.timestamp >= endsAt;
    }

    function principalOf(address user) external view returns (uint256) {
        return balanceOf[user] + coolingDown[user];
    }

    /// @notice Reward-token balance not reserved for stakers: rewards that streamed
    ///         while the pool was empty, plus direct donations. Reserved = already
    ///         streamed-but-unclaimed (rewardsOwed + accrual since last checkpoint)
    ///         + everything still scheduled through periodFinish.
    function recoverableRewards(address token) public view returns (uint256) {
        RewardData storage r = rewardData[token];
        uint256 applicable = lastTimeRewardApplicable(token);
        uint256 scheduled = r.periodFinish > applicable ? r.rewardRate * (r.periodFinish - applicable) : 0;
        uint256 pending;
        if (totalStaked != 0) {
            pending = Math.ceilDiv((rewardPerToken(token) - r.rewardPerTokenStored) * totalStaked, 1e18);
        }
        uint256 reserved = rewardsOwed[token] + pending + scheduled;
        uint256 bal = IERC20(token).balanceOf(address(this));
        return bal > reserved ? bal - reserved : 0;
    }

    function rewardTokensLength() external view returns (uint256) {
        return rewardTokens.length;
    }

    function getRewardTokens() external view returns (address[] memory) {
        return rewardTokens;
    }

    function addRewardToken(address token, address distributor) external onlyOwner {
        require(token != address(0), "zero token");
        require(distributor != address(0), "zero distributor");
        require(token != address(stakingToken), "staking token");
        require(!rewardData[token].exists, "already added");
        require(rewardTokens.length < MAX_REWARD_TOKENS, "too many tokens");
        rewardData[token].exists = true;
        rewardDistributor[token] = distributor;
        rewardTokens.push(token);
        emit RewardTokenAdded(token, distributor);
    }

    function notifyRewardAmount(address token, uint256 amount, uint256 duration)
        external
        nonReentrant
        onlyDistributor(token)
        updateReward(address(0))
    {
        RewardData storage r = rewardData[token];
        require(r.exists, "unknown reward token");
        require(amount > 0, "zero amount");
        require(duration >= MIN_DURATION && duration <= MAX_DURATION, "bad duration");
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
        if (block.timestamp >= r.periodFinish) {
            r.rewardRate = amount / duration;
        } else {
            uint256 remaining = r.periodFinish - block.timestamp;
            uint256 leftover = remaining * r.rewardRate;
            r.rewardRate = (amount + leftover) / duration;
        }
        require(r.rewardRate > 0, "reward rate zero");
        // Only balance not already owed to stakers may back the new schedule.
        uint256 balance = IERC20(token).balanceOf(address(this));
        uint256 owed = rewardsOwed[token];
        uint256 available = balance > owed ? balance - owed : 0;
        require(r.rewardRate <= available / duration, "reward exceeds balance");
        r.lastUpdateTime = uint64(block.timestamp);
        r.periodFinish = uint64(block.timestamp + duration);
        emit RewardNotified(token, amount, duration, r.rewardRate, r.periodFinish);
    }

    function setRewardDistributor(address token, address distributor) external onlyOwner {
        require(rewardData[token].exists, "unknown reward token");
        require(distributor != address(0), "zero distributor");
        rewardDistributor[token] = distributor;
        emit RewardDistributorUpdated(token, distributor);
    }

    function setCooldownPeriod(uint256 _cooldownPeriod) external onlyOwner {
        require(_cooldownPeriod <= MAX_COOLDOWN, "cooldown too long");
        cooldownPeriod = _cooldownPeriod;
        emit CooldownPeriodUpdated(_cooldownPeriod);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    /// @dev For registered reward tokens use recoverExcessRewardToken instead.
    function recoverERC20(address token, uint256 amount) external onlyOwner {
        require(token != address(stakingToken), "cannot recover staking token");
        require(!rewardData[token].exists, "cannot recover reward token");
        IERC20(token).safeTransfer(owner(), amount);
        emit Recovered(token, amount);
    }

    /// @notice Recover reward tokens in excess of what is owed and scheduled — e.g.
    ///         rewards that streamed while totalStaked was 0, or direct donations.
    ///         Cannot touch user-claimable balances: recoverableRewards reserves
    ///         streamed-but-unclaimed (ceil-rounded) plus the full remaining schedule.
    function recoverExcessRewardToken(address token, uint256 amount)
        external
        onlyOwner
        nonReentrant
        updateReward(address(0))
    {
        require(rewardData[token].exists, "unknown reward token");
        require(amount <= recoverableRewards(token), "exceeds excess");
        IERC20(token).safeTransfer(owner(), amount);
        emit RewardExcessRecovered(token, amount);
    }
}
